class Solution:
    def numUniqueEmailGroups(self, emails):
        groups = set()
        for e in emails:
            local, dom = e.split('@')
            local = local.split('+')[0].replace('.', '').lower()
            groups.add(local + '@' + dom.lower())
        return len(groups)

