class Solution {
public:
    int numUniqueEmailGroups(vector<string>& emails) {
        unordered_set<string> groups;
        for (string& e : emails) {
            size_t at = e.find('@');
            string local = e.substr(0, at), dom = e.substr(at + 1);
            string nl;
            for (char c : local) {
                if (c == '+') break;
                if (c != '.') nl += tolower(c);
            }
            for (char& c : dom) c = tolower(c);
            groups.insert(nl + "@" + dom);
        }
        return groups.size();
    }
};

