            int at = e.indexOf('@');
            String local = e.substring(0, at), dom = e.substring(at + 1).toLowerCase();
            StringBuilder nl = new StringBuilder();
            for (char c : local.toCharArray()) {
                if (c == '+') break;
                if (c != '.') nl.append(Character.toLowerCase(c));
