class Solution {
    public int numUniqueEmailGroups(String[] emails) {
        List<String> keys = new ArrayList<>();
        for (String e : emails) {
            int at = e.indexOf('@');
            String nl = e.substring(0, at).split("\\+")[0].replace(".", "").toLowerCase();
            keys.add(nl + "@" + e.substring(at + 1).toLowerCase());
        }
        Collections.sort(keys);
        int cnt = 0;
        for (int i = 0; i < keys.size(); i++)
            if (i == 0 || !keys.get(i).equals(keys.get(i-1))) cnt++;
        return cnt;
    }
}

